import{_ as l,C as d,o as i,c as r,a4 as t,j as n,E as s}from"./chunks/framework.BUqnS5H7.js";const q=JSON.parse('{"title":"数据页与行格式","description":"","frontmatter":{},"headers":[],"relativePath":"mysql/02-innodb-internals/chapter-01-data-page.md","filePath":"mysql/02-innodb-internals/chapter-01-data-page.md"}'),c={name:"mysql/02-innodb-internals/chapter-01-data-page.md"},p={"data-src-line":"11","data-src-file":"mysql/02-innodb-internals/chapter-01-data-page.md"},o={"data-src-line":"92","data-src-file":"mysql/02-innodb-internals/chapter-01-data-page.md"};function h(m,a,g,b,y,f){const e=d("SvgDiagram");return i(),r("div",null,[a[0]||(a[0]=t('<h1 id="数据页与行格式" tabindex="-1" data-src-line="1" data-src-file="mysql/02-innodb-internals/chapter-01-data-page.md">数据页与行格式 <a class="header-anchor" href="#数据页与行格式" aria-label="Permalink to &quot;数据页与行格式&quot;">​</a></h1><blockquote data-src-line="3" data-src-file="mysql/02-innodb-internals/chapter-01-data-page.md"><p data-src-line="3" data-src-file="mysql/02-innodb-internals/chapter-01-data-page.md">一条 <code>WHERE id = 500</code> 的主键查询，B+ 树经过 3 次磁盘 IO 定位到某个叶子页后，接下来要在这一页里几百条记录中找到 <code>id = 500</code> 的那一条。这一页内怎么找？如果顺序遍历，几百条就是几百次内存比较；InnoDB 用的是二分查找。但记录是靠单向链表串联的，单链表怎么二分？答案藏在页目录里。</p></blockquote><h2 id="_1-页的内部结构" tabindex="-1" data-src-line="5" data-src-file="mysql/02-innodb-internals/chapter-01-data-page.md">1. 页的内部结构 <a class="header-anchor" href="#_1-页的内部结构" aria-label="Permalink to &quot;1. 页的内部结构&quot;">​</a></h2><h3 id="_1-1-一个页里装了什么" tabindex="-1" data-src-line="7" data-src-file="mysql/02-innodb-internals/chapter-01-data-page.md">1.1 一个页里装了什么 <a class="header-anchor" href="#_1-1-一个页里装了什么" aria-label="Permalink to &quot;1.1 一个页里装了什么&quot;">​</a></h3><p data-src-line="9" data-src-file="mysql/02-innodb-internals/chapter-01-data-page.md">InnoDB 的磁盘 I/O 单位是<strong>页（Page）</strong>，默认 16KB。所有数据——表数据、索引、Undo Log——都组织成 16KB 的页。一个数据页从前往后分成七段：</p>',5)),n("p",p,[s(e,{src:"/mysql/02-innodb-internals-chapter-01-data-page.svg",alt:"InnoDB 数据页物理布局（16KB）"})]),a[1]||(a[1]=t(`<p data-src-line="13" data-src-file="mysql/02-innodb-internals/chapter-01-data-page.md">两段「头」和一段「尾」是元数据，<code>User Records</code> 与 <code>Page Directory</code> 从两端向中间增长，中间夹着的 <code>Free Space</code> 是尚可使用的空间。理解这一页内部怎么组织记录、怎么快速定位，是理解 B+ 树性能的最后一块拼图——<a href="./../03-index/chapter-01-btree-index.html">B+ 树索引</a> 讲的是「页与页之间怎么导航」，这一章讲「页内部怎么定位一条记录」。</p><h3 id="_1-2-记录怎么串联-next-record-单链表" tabindex="-1" data-src-line="15" data-src-file="mysql/02-innodb-internals/chapter-01-data-page.md">1.2 记录怎么串联：next_record 单链表 <a class="header-anchor" href="#_1-2-记录怎么串联-next-record-单链表" aria-label="Permalink to &quot;1.2 记录怎么串联：next_record 单链表&quot;">​</a></h3><p data-src-line="17" data-src-file="mysql/02-innodb-internals/chapter-01-data-page.md">页内的用户记录不按物理顺序排，而是靠每条记录头里的 <code>next_record</code> 指针串成一条<strong>单向链表</strong>，链表的逻辑顺序按主键从小到大：</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Infimum → 记录1(id=1) → 记录2(id=5) → ... → 记录N(id=500) → Supremum</span></span>
<span class="line"><span>（虚拟最小）                                              （虚拟最大）</span></span></code></pre></div><p data-src-line="24" data-src-file="mysql/02-innodb-internals/chapter-01-data-page.md">两个边界各是一条虚拟记录：</p><ul data-src-line="26" data-src-file="mysql/02-innodb-internals/chapter-01-data-page.md"><li data-src-line="26" data-src-file="mysql/02-innodb-internals/chapter-01-data-page.md"><strong>Infimum</strong>：逻辑上比页内任何记录都小，是链表的起点。</li><li data-src-line="27" data-src-file="mysql/02-innodb-internals/chapter-01-data-page.md"><strong>Supremum</strong>：逻辑上比页内任何记录都大，是链表的终点。</li></ul><p data-src-line="29" data-src-file="mysql/02-innodb-internals/chapter-01-data-page.md">关键点在于：这条链是<strong>逻辑有序、物理可能乱序</strong>的。删除一条记录后，它占的空间被标记为可复用；新插入的记录会落到 <code>Free Space</code> 里的某个空闲位置，物理上可能插在页的任意偏移，靠 <code>next_record</code> 指针把它接回正确的主键顺序。所以「记录按主键有序」是链表的逻辑顺序，不是它们在页内的物理排布。</p><p data-src-line="31" data-src-file="mysql/02-innodb-internals/chapter-01-data-page.md">这正是麻烦的起点：<strong>单链表只能从头顺序遍历</strong>。要在几百条记录里找 <code>id = 500</code>，顺着 <code>next_record</code> 一条条走，平均要走一半。内存里走几百步并不慢，但页目录提供了一条更快的路。</p><h3 id="_1-3-页目录-让单链表也能二分" tabindex="-1" data-src-line="33" data-src-file="mysql/02-innodb-internals/chapter-01-data-page.md">1.3 页目录：让单链表也能二分 <a class="header-anchor" href="#_1-3-页目录-让单链表也能二分" aria-label="Permalink to &quot;1.3 页目录：让单链表也能二分&quot;">​</a></h3><p data-src-line="35" data-src-file="mysql/02-innodb-internals/chapter-01-data-page.md">页目录（Page Directory）的职责，就是把「只能顺序遍历的单链表」改造成「可以二分查找」的结构。它做了两件事：</p><ol data-src-line="37" data-src-file="mysql/02-innodb-internals/chapter-01-data-page.md"><li data-src-line="37" data-src-file="mysql/02-innodb-internals/chapter-01-data-page.md">把链表上的记录<strong>分组</strong>，每 4~8 条为一组，每个组叫一个<strong>槽（slot）</strong>；</li><li data-src-line="38" data-src-file="mysql/02-innodb-internals/chapter-01-data-page.md">每个槽只记录一件事：<strong>这一组里最后一条记录</strong>在页内的偏移量（即指向它的指针）。</li></ol><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>页目录（slot 数组，按主键有序）</span></span>
<span class="line"><span>┌────────────────────────────────────┐</span></span>
<span class="line"><span>│ slot0 → Infimum                    │</span></span>
<span class="line"><span>│ slot1 → 记录(id=4)   ← 组1的最后一条 │</span></span>
<span class="line"><span>│ slot2 → 记录(id=8)   ← 组2的最后一条 │</span></span>
<span class="line"><span>│ slot3 → 记录(id=12)  ← 组3的最后一条 │</span></span>
<span class="line"><span>│ slotN → Supremum                   │</span></span>
<span class="line"><span>└────────────────────────────────────┘</span></span></code></pre></div><p data-src-line="51" data-src-file="mysql/02-innodb-internals/chapter-01-data-page.md">slot 数组本身按主键<strong>严格有序</strong>（因为每组最后一条是递增的），所以可以在这个数组上做二分查找：先确定目标记录落在哪个 slot，再进入该 slot 对应的组内，顺序遍历最多 8 条就能找到。</p><p data-src-line="53" data-src-file="mysql/02-innodb-internals/chapter-01-data-page.md">这就是「单链表也能二分」的全部秘密：<strong>链表本身没有随机访问能力，但页目录把链表抽样成了一组有序指针，二分查找发生在 slot 数组上，而不是链表上。</strong> 查找 <code>id = 500</code> 的过程是：二分 slot 数组定位到某个 slot → 在该 slot 覆盖的 4~8 条记录里顺序比较 → 命中。</p><p data-src-line="55" data-src-file="mysql/02-innodb-internals/chapter-01-data-page.md">页目录的大小随记录数增长，但每个 slot 只存一个 2 字节偏移量，几百条记录对应几十个 slot，开销可忽略。这是「用一点点冗余的目录，换页内查找从 O(n) 降到 O(log n)」的典型设计。</p><h2 id="_2-行格式与行溢出" tabindex="-1" data-src-line="57" data-src-file="mysql/02-innodb-internals/chapter-01-data-page.md">2. 行格式与行溢出 <a class="header-anchor" href="#_2-行格式与行溢出" aria-label="Permalink to &quot;2. 行格式与行溢出&quot;">​</a></h2><h3 id="_2-1-一条记录怎么存-compact-行格式" tabindex="-1" data-src-line="59" data-src-file="mysql/02-innodb-internals/chapter-01-data-page.md">2.1 一条记录怎么存：Compact 行格式 <a class="header-anchor" href="#_2-1-一条记录怎么存-compact-行格式" aria-label="Permalink to &quot;2.1 一条记录怎么存：Compact 行格式&quot;">​</a></h3><p data-src-line="61" data-src-file="mysql/02-innodb-internals/chapter-01-data-page.md">页里的每条记录，按行格式组织。MySQL 8.0 之前默认 <code>Compact</code>，之后默认 <code>Dynamic</code>，两者主体一致，只有大字段处理不同。</p><p data-src-line="63" data-src-file="mysql/02-innodb-internals/chapter-01-data-page.md"><code>Compact</code> 格式的一条记录从前往后：</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌─────────────────────┐</span></span>
<span class="line"><span>│ 变长字段长度列表       │  每个变长字段的实际字节数（逆序存放）</span></span>
<span class="line"><span>├─────────────────────┤</span></span>
<span class="line"><span>│ NULL 标志位          │  哪些列是 NULL（位图，1 位对应 1 列）</span></span>
<span class="line"><span>├─────────────────────┤</span></span>
<span class="line"><span>│ 记录头信息            │  5 字节：next_record、记录类型、删除标记等</span></span>
<span class="line"><span>├─────────────────────┤</span></span>
<span class="line"><span>│ 隐藏列               │  DB_ROW_ID / DB_TRX_ID / DB_ROLL_PTR</span></span>
<span class="line"><span>├─────────────────────┤</span></span>
<span class="line"><span>│ 用户数据              │  你定义的各列</span></span>
<span class="line"><span>└─────────────────────┘</span></span></code></pre></div><p data-src-line="79" data-src-file="mysql/02-innodb-internals/chapter-01-data-page.md">记录头里的 <code>next_record</code> 就是上一节串链表的那个指针——它存的是「下一条记录相对本记录的偏移量」，指向逻辑上的下一条，而非物理相邻的下一条。隐藏列 <code>DB_TRX_ID</code> 与 <code>DB_ROLL_PTR</code> 是 MVCC 版本链的载体，见 <a href="./../04-transaction-lock/chapter-01-transaction.html#hidden-columns">事务与 MVCC §2.2</a>。</p><h3 id="_2-2-行溢出-一行太大怎么办" tabindex="-1" data-src-line="81" data-src-file="mysql/02-innodb-internals/chapter-01-data-page.md">2.2 行溢出：一行太大怎么办 <a class="header-anchor" href="#_2-2-行溢出-一行太大怎么办" aria-label="Permalink to &quot;2.2 行溢出：一行太大怎么办&quot;">​</a></h3><p data-src-line="83" data-src-file="mysql/02-innodb-internals/chapter-01-data-page.md">一个页 16KB，其中可放用户数据的部分远小于 16KB（要扣掉头尾、页目录、Free Space 余量）。InnoDB 约定：<strong>一行记录超过页大小的一半（约 8KB）时，触发行溢出</strong>，把超大的列搬到独立的溢出页。</p><p data-src-line="85" data-src-file="mysql/02-innodb-internals/chapter-01-data-page.md">两种行格式对溢出的处理不同：</p><table tabindex="0"><thead data-src-line="87" data-src-file="mysql/02-innodb-internals/chapter-01-data-page.md"><tr data-src-line="87" data-src-file="mysql/02-innodb-internals/chapter-01-data-page.md"><th style="text-align:left;">格式</th><th style="text-align:left;">溢出策略</th><th style="text-align:left;">当前页保留</th></tr></thead><tbody data-src-line="89" data-src-file="mysql/02-innodb-internals/chapter-01-data-page.md"><tr data-src-line="89" data-src-file="mysql/02-innodb-internals/chapter-01-data-page.md"><td style="text-align:left;"><code>Compact</code></td><td style="text-align:left;">大字段前 768 字节留在本页，其余进溢出页</td><td style="text-align:left;">768 字节 + 20 字节指针</td></tr><tr data-src-line="90" data-src-file="mysql/02-innodb-internals/chapter-01-data-page.md"><td style="text-align:left;"><code>Dynamic</code>（8.0 默认）</td><td style="text-align:left;">大字段整体进溢出页</td><td style="text-align:left;">仅 20 字节指针</td></tr></tbody></table>`,25)),n("p",o,[s(e,{src:"/mysql/02-innodb-internals-chapter-01-data-page-row-overflow.svg",alt:"行溢出：大字段如何存进溢出页"})]),a[2]||(a[2]=t(`<p data-src-line="94" data-src-file="mysql/02-innodb-internals/chapter-01-data-page.md"><code>Dynamic</code> 把「留 768 字节」这一步也去掉了，只在本页存 20 字节指针。收益是当前页能容纳更多行，代价是读这条大字段要多一次「跳溢出页」的 IO。这也是「TEXT/BLOB 列单独拆表」的依据——把它们留在主表里，会让主表的行频繁溢出，拖慢整行扫描。</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">-- 查看表的行格式</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">SELECT</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> table_name, row_format</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">FROM</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> information_schema</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">tables</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">WHERE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> table_schema </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;mydb&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span></code></pre></div><h2 id="_3-页分裂与页类型" tabindex="-1" data-src-line="103" data-src-file="mysql/02-innodb-internals/chapter-01-data-page.md">3. 页分裂与页类型 <a class="header-anchor" href="#_3-页分裂与页类型" aria-label="Permalink to &quot;3. 页分裂与页类型&quot;">​</a></h2><h3 id="_3-1-页分裂-从页内部看" tabindex="-1" data-src-line="105" data-src-file="mysql/02-innodb-internals/chapter-01-data-page.md">3.1 页分裂：从页内部看 <a class="header-anchor" href="#_3-1-页分裂-从页内部看" aria-label="Permalink to &quot;3.1 页分裂：从页内部看&quot;">​</a></h3><p data-src-line="107" data-src-file="mysql/02-innodb-internals/chapter-01-data-page.md">插入记录时，如果页内 <code>Free Space</code> 装不下新记录，就要<strong>页分裂</strong>：申请一个新页，把原页里约一半的记录挪过去，再在父节点登记新页。</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>原页 [1, 3, 5, 7, 9] 要插入 6，Free Space 已满：</span></span>
<span class="line"><span>  → 申请新页</span></span>
<span class="line"><span>  → 后半部分移到新页：原页 [1, 3, 5] + 新页 [6, 7, 9]</span></span>
<span class="line"><span>  → 父节点新增一个指向新页的指针</span></span></code></pre></div><p data-src-line="116" data-src-file="mysql/02-innodb-internals/chapter-01-data-page.md">页分裂的代价不在「搬记录」本身，而在三处：</p><ul data-src-line="118" data-src-file="mysql/02-innodb-internals/chapter-01-data-page.md"><li data-src-line="118" data-src-file="mysql/02-innodb-internals/chapter-01-data-page.md"><strong>随机 IO</strong>：新页在表空间文件里的位置与旧页不相邻，磁头要跳到新位置；</li><li data-src-line="119" data-src-file="mysql/02-innodb-internals/chapter-01-data-page.md"><strong>空间利用率下降</strong>：分裂后两个页各只满一半，约 50% 空间被浪费；</li><li data-src-line="120" data-src-file="mysql/02-innodb-internals/chapter-01-data-page.md"><strong>树增高</strong>：若父节点也满了，分裂会向上传导，最坏让 B+ 树多一层。</li></ul><p data-src-line="122" data-src-file="mysql/02-innodb-internals/chapter-01-data-page.md">顺序主键（<code>AUTO_INCREMENT</code>）插入时，新记录永远落在「最后」一页，装满才开新页，几乎不分裂；随机主键（UUID）插入时，新记录落在任意页的任意位置，频繁触发分裂。这个选择在 <a href="./../03-index/chapter-01-btree-index.html#page-split">B+ 树索引 §3.2</a> 从主键选型角度展开，本章从页内部解释「为什么随机主键伤性能」。</p><h3 id="_3-2-页类型" tabindex="-1" data-src-line="124" data-src-file="mysql/02-innodb-internals/chapter-01-data-page.md">3.2 页类型 <a class="header-anchor" href="#_3-2-页类型" aria-label="Permalink to &quot;3.2 页类型&quot;">​</a></h3><p data-src-line="126" data-src-file="mysql/02-innodb-internals/chapter-01-data-page.md">同一套 16KB 页结构，靠 <code>File Header</code> 里的类型字段区分用途：</p><table tabindex="0"><thead data-src-line="128" data-src-file="mysql/02-innodb-internals/chapter-01-data-page.md"><tr data-src-line="128" data-src-file="mysql/02-innodb-internals/chapter-01-data-page.md"><th style="text-align:left;">页类型</th><th style="text-align:left;">用途</th></tr></thead><tbody data-src-line="130" data-src-file="mysql/02-innodb-internals/chapter-01-data-page.md"><tr data-src-line="130" data-src-file="mysql/02-innodb-internals/chapter-01-data-page.md"><td style="text-align:left;"><code>FIL_PAGE_INDEX</code></td><td style="text-align:left;">B+ 树索引页，最常见</td></tr><tr data-src-line="131" data-src-file="mysql/02-innodb-internals/chapter-01-data-page.md"><td style="text-align:left;"><code>FIL_PAGE_UNDO_LOG</code></td><td style="text-align:left;">Undo Log 页</td></tr><tr data-src-line="132" data-src-file="mysql/02-innodb-internals/chapter-01-data-page.md"><td style="text-align:left;"><code>FIL_PAGE_INODE</code></td><td style="text-align:left;">段内索引节点页</td></tr><tr data-src-line="133" data-src-file="mysql/02-innodb-internals/chapter-01-data-page.md"><td style="text-align:left;"><code>FIL_PAGE_IBUF_FREE_LIST</code></td><td style="text-align:left;">Change Buffer 空闲列表页</td></tr><tr data-src-line="134" data-src-file="mysql/02-innodb-internals/chapter-01-data-page.md"><td style="text-align:left;"><code>FIL_PAGE_TYPE_ALLOCATED</code></td><td style="text-align:left;">已分配未使用</td></tr></tbody></table><h2 id="_4-最佳实践" tabindex="-1" data-src-line="136" data-src-file="mysql/02-innodb-internals/chapter-01-data-page.md">4. 最佳实践 <a class="header-anchor" href="#_4-最佳实践" aria-label="Permalink to &quot;4. 最佳实践&quot;">​</a></h2><ol data-src-line="138" data-src-file="mysql/02-innodb-internals/chapter-01-data-page.md"><li data-src-line="138" data-src-file="mysql/02-innodb-internals/chapter-01-data-page.md"><strong>顺序主键</strong>（<code>AUTO_INCREMENT</code>）——避免页分裂，见 §3.1。</li><li data-src-line="139" data-src-file="mysql/02-innodb-internals/chapter-01-data-page.md"><strong>避免 UUID 主键</strong>——随机写入导致频繁页分裂。</li><li data-src-line="140" data-src-file="mysql/02-innodb-internals/chapter-01-data-page.md"><strong>大字段用 <code>Dynamic</code> 行格式</strong>——8.0 默认，溢出只留 20 字节指针。</li><li data-src-line="141" data-src-file="mysql/02-innodb-internals/chapter-01-data-page.md"><strong>TEXT/BLOB 单独拆表</strong>——减少主表行溢出。</li><li data-src-line="142" data-src-file="mysql/02-innodb-internals/chapter-01-data-page.md"><strong>控制单行大小</strong>——单行尽量不超 8KB，避免动不动就走溢出页。</li></ol>`,14))])}const u=l(c,[["render",h]]);export{q as __pageData,u as default};
